Rules.InvariantScript:
"Qty Items: " & Coalesce(
    Sum(
        Filter(
            'RigheOrdini-BC',
            'Nr documento' in Filter('Ordini-BC', 'ID-Cliente' = Value(ThisItem.ID)).Nr
        ),
        Quantità
    ),
    0
)

"Total: " & Text(
    Coalesce(
        Sum(
            Filter(
                'RigheOrdini-BC',
                'Nr documento' in Filter('Ordini-BC', 'ID-Cliente' = Value(ThisItem.ID)).Nr
            ),
            Importo
        ),
        0
    ),
    "€ #,##0.00"
)

SubmitForm(Form2); 
UpdateContext({varMostraNuovoCliente: false}); 
Notify("Cliente salvato correttamente!", NotificationType.Success)

If(
    varPopupNuovoCliente,
    Reset(txtNuovoNome); Reset(txtNuovoContatto); Reset(txtNuovoIndirizzo);
    Reset(txtNuovoCitta); Reset(txtNuovoProvincia); Reset(txtNuovoCAP);
    Set(varPopupNuovoCliente, false),
    varPopupElimina,
    Set(varPopupElimina, false),
    varPopupCliente,
    Set(varPopupCliente, false)
)

Patch('Clienti-BC', LookUp('Clienti-BC', ID = varClienteSel.ID), { 'Cod agente': drpNuovoAgente.Selected.Value });
Set(varPopupAssegnaAgente, false);
Notify("Nuovo agente assegnato", NotificationType.Success);

Set(varClienteModifica, varClienteSel);
Reset(txtNuovoNome); Reset(txtNuovoContatto); Reset(txtNuovoIndirizzo);
Reset(txtNuovoCitta); Reset(txtNuovoProvincia); Reset(txtNuovoCAP);
Set(varPopupNuovoCliente, true)

Set(varClienteOrdine, varClienteSel);
Set(varOrdineAttivo, true);
ClearCollect(colRigheOrdine, []);
Set(varPopupCliente, false);
Navigate(scrProducts)

Patch('Clienti-BC', LookUp('Clienti-BC', ID = varClienteSel.ID), { Attivo: false });
Set(varPopupCliente, false);
Notify("Cliente disattivato definitivamente", NotificationType.Success)

Patch(
    'Notifiche-BC',
    Defaults('Notifiche-BC'),
    {
        Title: "Richiesta distacco: " & varClienteSel.Nome,
        TipoNotifica: { Value: "RichiestaDistaccoCliente" },
        Mittente: Left(varUtenteCorrente.Email, Find("@", varUtenteCorrente.Email) - 1),
        Destinatario: "Manager",
        Messaggio: "Richiesta distacco per " & varClienteSel.Nome & " (ID " & varClienteSel.ID & ") — " & InptMotivazione.Text,
        Letta: false,
        Data: Now(),
        LinkRif: Text(varClienteSel.ID)
    }
);
Notify("Richiesta inviata al Manager", NotificationType.Success);
Reset(InptMotivazione);
Set(varPopupCliente, false)

If(
    IsBlank(txtNuovoNome.Text),
    Notify("Il nome è obbligatorio", NotificationType.Error),
    Patch(
    'Clienti-BC',
    If(IsBlank(varClienteModifica), Defaults('Clienti-BC'), varClienteModifica),
    {
        Nome: txtNuovoNome.Text,
        Contatto: txtNuovoContatto.Text,
        Indirizzo: txtNuovoIndirizzo.Text,
        Città: txtNuovoCitta.Text,
        Provincia: txtNuovoProvincia.Text,
        CAP: txtNuovoCAP.Text
    }
);
    Notify(If(IsBlank(varClienteModifica), "Cliente creato!", "Cliente aggiornato!"), NotificationType.Success);
    Set(varClienteModifica, Blank());
    Set(varPopupNuovoCliente, false)
)

Reset(txtNuovoNome); Reset(txtNuovoContatto); Reset(txtNuovoIndirizzo);
Reset(txtNuovoCitta); Reset(txtNuovoProvincia); Reset(txtNuovoCAP);
Set(varPopupNuovoCliente, false)

ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(txtNuovoNome.Text),
    Notify("Il nome è obbligatorio", NotificationType.Error),
    Patch(
        'Clienti-BC',
        Defaults('Clienti-BC'),
        {
            Nome: txtNuovoNome.Text,
            Contatto: txtNuovoContatto.Text,
            Indirizzo: txtNuovoIndirizzo.Text,
            Città: txtNuovoCitta.Text,
            Provincia: txtNuovoProvincia.Text,
            CAP: txtNuovoCAP.Text
        }
    );
    Notify("Cliente creato!", NotificationType.Success);
    Reset(txtNuovoNome); Reset(txtNuovoContatto); Reset(txtNuovoIndirizzo);
    Reset(txtNuovoCitta); Reset(txtNuovoProvincia); Reset(txtNuovoCAP);
    Set(varPopupNuovoCliente, false)
)

Rules.InvariantScript:
Patch(
    'Notifiche-BC',
    Defaults('Notifiche-BC'),
    {
        Title: "Richiesta eliminazione: " & varClienteSel.Nome,
        TipoNotifica: { Value: "RichiestaEliminazioneCliente" },
        Mittente: Left(varUtenteCorrente.Email, Find("@", varUtenteCorrente.Email) - 1),
        Destinatario: "Manager",
        Messaggio: "Richiesta eliminazione per " & varClienteSel.Nome & " (ID " & varClienteSel.ID & ") — " & InptMotivazione.Text,
        Letta: false,
        Data: Now(),
        LinkRif: Text(varClienteSel.ID)
    }
);
Notify("Richiesta inviata al Manager", NotificationType.Success);
Reset(InptMotivazione);
Set(varPopupElimina, false)

Navigate(scrProducts, ScreenTransition.Fade);
Set(varOrdineAttivo, false);
Set(varClienteOrdine, Blank());
Clear(colRigheOrdine);
Navigate(scrProducts)

ControlPropertyState.AutoRuleBindingString:
Set(varClienteModifica, Blank());
Reset(txtNuovoNome); Reset(txtNuovoContatto); Reset(txtNuovoIndirizzo);
Reset(txtNuovoCitta); Reset(txtNuovoProvincia); Reset(txtNuovoCAP);
Set(varPopupNuovoCliente, true)

Rules.InvariantScript:
Set(varClienteModifica, Blank());
Reset(txtNuovoNome); Reset(txtNuovoContatto); Reset(txtNuovoIndirizzo);
Reset(txtNuovoCitta); Reset(txtNuovoProvincia); Reset(txtNuovoCAP);
Set(varPopupNuovoCliente, true)
